head.script:
scwin.onpageload = function () {
    var selectBoxObj = [
        { "label": "A", "value": "A" },
        { "label": "B", "value": "B" },
        { "label": "C", "value": "C" },
        { "label": "D", "value": "D" },
    ];
    categoryData.setJSON(selectBoxObj);

    var selectBoxObj2 = [
        { "subCategoryGubun": "A", "value": "A1", "label": "A중분류-1" },
        { "subCategoryGubun": "A", "value": "A2", "label": "A중분류-2" },
        { "subCategoryGubun": "A", "value": "A3", "label": "A중분류-3" },
        { "subCategoryGubun": "A", "value": "A4", "label": "A중분류-4" },
        { "subCategoryGubun": "A", "value": "A5", "label": "A중분류-5" },
        { "subCategoryGubun": "A", "value": "A6", "label": "A중분류-6" },
        { "subCategoryGubun": "A", "value": "A7", "label": "A중분류-7" },
        { "subCategoryGubun": "A", "value": "A8", "label": "A중분류-8" },
        { "subCategoryGubun": "A", "value": "A9", "label": "A중분류-9" },
        { "subCategoryGubun": "A", "value": "A10", "label": "A중분류-10" },
        { "subCategoryGubun": "A", "value": "A11", "label": "A중분류-11" },
        { "subCategoryGubun": "A", "value": "A12", "label": "A중분류-12" },
        { "subCategoryGubun": "A", "value": "A13", "label": "A중분류-13" },
        { "subCategoryGubun": "A", "value": "A14", "label": "A중분류-14" },
        { "subCategoryGubun": "A", "value": "A15", "label": "A중분류-15" },
    ];
    subCategoryData.setJSON(selectBoxObj2);

    selectBoxObj2 = [
        { "subCategoryGubun": "B", "value": "B1", "label": "B중분류-1" },
        { "subCategoryGubun": "B", "value": "B2", "label": "B중분류-2" }
    ];
    subCategoryData2.setJSON(selectBoxObj2);

    selectBoxObj2 = [
        { "subCategoryGubun": "C", "value": "C1", "label": "C중분류-1" },
        { "subCategoryGubun": "C", "value": "C2", "label": "C중분류-2" }
