        { "subCategoryGubun": "D", "value": "D2", "label": "D중분류-2" }
    ];
    subCategoryData4.setJSON(selectBoxObj2);
    var gridDataObj = [
    ];


    // selectBoxObj 수 만큼 행 추가
    gridViewData.setJSON(selectBoxObj);
    // 정적으로 직접 행 추가
    // gridViewData.insertRow();
    // gridViewData.insertRow();
    // gridViewData.insertRow();
}


// 대분류 선택 시마다 이벤트 실행
scwin.gridView1_onviewchange = function (info) {
    console.log("gridView onviewchange", info);
    if (info.colIndex == 0) {
        var cellObj = {};
        if (info.newValue == "A") {
            cellObj = {
                inputType: "autoComplete",
                options: {
                    chooseOption: true,
                    chooseOptionLabel: "선택",
                    embeddedInput : true
                },
                itemSet: {
                    nodeset: "data:subCategoryData",
                    label: "label",
                    value: "value"
                }
            }
        } else if (info.newValue == "B") {
            cellObj = {
                inputType: "select",
                options: { viewType: "icon",
                    embeddedInput : true },
                itemSet: {
                    nodeset: "data:subCategoryData2",
                    label: "label",
                    value: "value"
                }
            }
        } else if (info.newValue == "C") {
            cellObj = {
                inputType: "select",
                options: { viewType: "icon" },
                itemSet: {
                    nodeset: "data:subCategoryData3",
                    label: "label",
                    value: "value"
                }
            }
        } else {
            cellObj = {
                inputType: "select",
                options: { viewType: "icon" },
                itemSet: {
                    nodeset: "data:subCategoryData4",
                    label: "label",
                    value: "value"
                }
            }
        }
        gridView1.setCellInputType(info.rowIndex, "col2", cellObj);
    }
};

	scwin.setVal1 = function() {
	    let info1 = {};
		info1.colIndex = 0;
		info1.newValue = "A";
		info1.colId = "col1";
		info1.rowIndex = 0;
		info1.oldValue = "";
		info1.newSelectedIndex = 1;
		info1.oldSelectedIndex = 0;

		scwin.gridView1_onviewchange(info1);
	}	

	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#gridView1_dynamic_autoComplete_0_1_input', 'key-sequence', {
			sequence: 'A중분류-1'
		});
	}	
	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}	
	scwin.setSimulate2 = function() {
		scwin.simulateWrapper2('#gridView1_cell_0_0');
	}
	scwin.setSimulate3 = function() {
		scwin.simulateWrapper2('#gridView1_cell_0_2');
	}	
	scwin.simulateWrapper2 = function(target) {
		WebSquare.wUnit.getJq(target).simulate("click");
	}	
	scwin.setVal2 = function() {
		WebSquare.wUnit.getDomById('gridView1_dynamic_autoComplete_0_1_input').value='A중분류-1'

	}		
	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('gridView1_dynamic_autoComplete_0_1_input').value == 'A중분류-1';
	}		
	scwin.unitTest = function() {
		//noResult="previous"
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setVal1()");	
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_dynamic_autoComplete_0_1_input').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_dynamic_autoComplete_0_1_input').focus()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
